toolItems.command:
/usr/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f6f3eb">
  <title>FIELD NOTES — A quiet study.</title>
  <style>
    :root {
      color-scheme: light;
      --paper: #f6f3eb;
      --ink: #163b43;
      --ochre: #f1b85b;
    }

    * { box-sizing: border-box; }

    html { background: var(--paper); }

    body {
      margin: 0;
      color: var(--ink);
      background: var(--paper);
      font-family: Arial, Helvetica, sans-serif;
      font-weight: 400;
    }

    .page {
      width: 100%;
      padding: 50px 64px 40px;
    }

    .masthead {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      padding-right: 32px;
      line-height: 24px;
    }

    .wordmark { font-size: 20px; }
    .work-link { font-size: 18px; }

    a { color: inherit; text-decoration: none; }
    a:focus-visible { outline: 2px solid var(--ink); outline-offset: 6px; }
    .work-link:hover { text-decoration: underline; text-underline-offset: 4px; }

    .intro { margin-top: 98px; }

    h1 {
      margin: 0;
      font-size: 72px;
      font-weight: 400;
      line-height: 86px;
    }

    .intro p {
      margin: 20px 0 0;
      font-size: 24px;
      line-height: 29px;
    }

    .explore {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 160px;
      height: 60px;
      margin-top: 33px;
      border-radius: 0;
      color: var(--paper);
      background: var(--ink);
      font-size: 22px;
      line-height: 1;
    }

    .image-area {
      display: block;
      width: 100%;
      height: auto;
      margin-top: 60px;
      background: var(--ink);
    }

    #work { margin-top: 57px; }

    h2 {
      margin: 0;
      font-size: 36px;
      font-weight: 400;
      line-height: 43px;
    }

    @media (max-width: 700px) {
      .page { padding: 32px 24px 36px; }
      .masthead { padding-right: 0; }
      .intro { margin-top: 76px; }
      h1 { font-size: clamp(40px, 8.8vw, 62px); line-height: 1.2; }
      .intro p { font-size: 20px; line-height: 1.4; }
      .explore { margin-top: 28px; }
      .image-area { margin-top: 48px; }
      #work { margin-top: 42px; }
      h2 { font-size: 30px; line-height: 1.2; }
    }
  </style>
</head>
<body>
  <div class="page">
    <header class="masthead">
      <span class="wordmark">FIELD NOTES</span>
      <nav aria-label="Main"><a class="work-link" href="#work">Work</a></nav>
    </header>
    <main>
      <section class="intro" aria-labelledby="intro-title">
        <h1 id="intro-title">A quiet study.</h1>
        <p>An independent film practice.</p>
        <a class="explore" href="#work">Explore</a>
      </section>
      <svg class="image-area" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1072 300" aria-hidden="true" focusable="false">
        <rect width="1072" height="300" fill="#163b43"/>
        <circle cx="866" cy="150" r="90" fill="#f1b85b"/>
      </svg>
      <section id="work" aria-labelledby="work-title">
        <h2 id="work-title">Selected work</h2>
      </section>
    </main>
  </div>
</body>
</html>
EOF
